332	const replaceCaret = (comp, options) => {
333	  debug('caret', comp, options)
334	  const r = options.loose ? re[t.CARETLOOSE] : re[t.CARET]
335	  const z = options.includePrerelease ? '-0' : ''
336	  return comp.replace(r, (_, M, m, p, pr) => {
337	    debug('caret', comp, _, M, m, p, pr)
338	    let ret
339	
340	    if (isX(M)) {
341	      ret = ''
342	    } else if (isX(m)) {
343	      ret = `>=${M}.0.0${z} <${+M + 1}.0.0-0`
344	    } else if (isX(p)) {
345	      if (M === '0') {
346	        ret = `>=${M}.${m}.0${z} <${M}.${+m + 1}.0-0`
347	      } else {
348	        ret = `>=${M}.${m}.0${z} <${+M + 1}.0.0-0`
349	      }
350	    } else if (pr) {
351	      debug('replaceCaret pr', pr)
352	      if (M === '0') {
353	        if (m === '0') {
354	          ret = `>=${M}.${m}.${p}-${pr
355	          } <${M}.${m}.${+p + 1}-0`
356	        } else {
357	          ret = `>=${M}.${m}.${p}-${pr
358	          } <${M}.${+m + 1}.0-0`
359	        }
360	      } else {
361	        ret = `>=${M}.${m}.${p}-${pr
362	        } <${+M + 1}.0.0-0`
363	      }
364	    } else {
365	      debug('no pr')
366	      if (M === '0') {
367	        if (m === '0') {
368	          ret = `>=${M}.${m}.${p
369	          }${z} <${M}.${m}.${+p + 1}-0`
370	        } else {
371	          ret = `>=${M}.${m}.${p
372	          }${z} <${M}.${+m + 1}.0-0`
373	        }
374	      } else {
375	        ret = `>=${M}.${m}.${p
376	        } <${+M + 1}.0.0-0`
377	      }
378	    }
379	
380	    debug('caret return', ret)
381	    return ret
382	  })
383	}
384	
385	const replaceXRanges = (comp, options) => {
386	  debug('replaceXRanges', comp, options)
387	  return comp
388	    .split(/\s+/)
389	    .map((c) => replaceXRange(c, options))
390	    .join(' ')
391	}
